using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
public static class B4FinishArt {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B4/";
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("B4 edit required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
  string path=E+"BO_C01_Skirting.fbx";var m=(ModelImporter)AssetImporter.GetAtPath(path);m.importAnimation=false;m.importCameras=false;m.importLights=false;m.isReadable=true;m.importNormals=ModelImporterNormals.Import;m.importTangents=ModelImporterTangents.CalculateMikk;m.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;
  foreach(var key in new[]{"Steel","Coat"})m.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"B4O_"+key),AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/B4O_"+key+".mat"));m.SaveAndReimport();
  var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform;var shell=root.Find("B4_C01_건축");if(!shell.Find("B4_C01_벽하단_밀폐마감")){var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),shell);go.name="B4_C01_벽하단_밀폐마감";go.transform.localPosition=Vector3.zero;PrefabUtility.RecordPrefabInstancePropertyModifications(go);PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);}
  string support="Assets/Afrer_Seconds/05.Model/Props/B4/BO_TrackingCameraSupport.fbx";var si=(ModelImporter)AssetImporter.GetAtPath(support);si.importAnimation=false;si.importCameras=false;si.importLights=false;si.isReadable=true;si.importNormals=ModelImporterNormals.Import;si.importTangents=ModelImporterTangents.CalculateMikk;si.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;si.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"B4O_Steel"),AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/B4O_Steel.mat"));si.SaveAndReimport();
  var props=root.Find("B4_C01_관측설비");for(int i=0;i<4;i++){string n="B4_C01_추적카메라_벽고정대_"+(i+1).ToString("00");if(props.Find(n))continue;float a=(22.5f+i*90)*Mathf.Deg2Rad;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(support),props);g.name=n;g.transform.localPosition=dir*11.30f+Vector3.up*4.13f;g.transform.localRotation=Quaternion.LookRotation(-dir);PrefabUtility.RecordPrefabInstancePropertyModifications(g);PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);}
  EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{saved=s.path};
 }
}
